class CoCoMEOrderProducts_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find the order with provided order id
   *if it is not exist,
   *create the order product with the status new and the id is order id,
   *and the time is now,
   *then save it*/
  makeNewOrder(orderid: number): boolean {
    /*Definition Start*/
    let orderProduct: OrderProduct = l({
      logic: () =>
        getRepository(OrderProduct).filter(
          (o: any) =>
            l({
              logic: () => o.Id === orderid,
              description: "o.Id=orderid",
            }).build().pass,
        ),
      description: "OrderProduct.allInstance()->select(o|o.Id=orderid)",
    }).build().pass;
    let isExist: boolean = l({
      logic: () => getRepository(OrderProduct).includes(orderProduct),
      description: "OrderProduct.allInstance()->includes(orderProduct)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () =>
          isExist === getRepository(OrderProduct).includes(orderProduct),
        description:
          "isExist=OrderProduct.allInstance()->includes(orderProduct)",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let orderProduct: OrderProduct;
    return l({
      execute: () => (orderProduct = new OrderProduct()),
      description: "orderProduct.oclIsNew()",
    })
      .and({
        execute: () => getRepository(OrderProduct).push(orderProduct),
        description: "OrderProduct.allInstance()->includes(orderProduct)",
      })
      .and({
        execute: () => isExist,
        description: "result=isExist",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { CoCoMEOrderProducts_AutoGenerated };

